package com.doms.doms.controller;
import com.doms.doms.dto.*;import com.doms.doms.service.DepartmentService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/departments") @RequiredArgsConstructor
public class DepartmentController {private final DepartmentService service;@GetMapping public ResponseEntity<List<LookupResponse>> all(){return ResponseEntity.ok(service.findAll());}@GetMapping("/trash") public ResponseEntity<List<LookupTrashResponse>> trash(){return ResponseEntity.ok(service.trash());}@PostMapping public ResponseEntity<LookupResponse> create(@Valid @RequestBody LookupRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@PutMapping("/{id}") public ResponseEntity<LookupResponse> update(@PathVariable Long id,@Valid @RequestBody LookupRequest r){return ResponseEntity.ok(service.update(id,r));}@PutMapping("/{id}/restore") public ResponseEntity<Void> restore(@PathVariable Long id){service.restore(id);return ResponseEntity.noContent().build();}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}@DeleteMapping("/{id}/permanent") public ResponseEntity<Void> purge(@PathVariable Long id){service.purge(id);return ResponseEntity.noContent().build();}}
